import type { AgentsConfig, SpokeDefinitionId } from '@qa-ai-stlc/schemas';

/** Marks a subagent file the engine wrote, so a later run only ever overwrites its own output. */
export const GENERATED_SUBAGENT_MARKER =
  '<!-- Generated by "qa agents generate" from agents.models in .qa/config.yaml. Change the config and run it again; edits here are not kept. -->';

export const SUBAGENT_DIRECTORY = '.claude/agents';

interface SpokeSubagentDefinition {
  readonly id: SpokeDefinitionId;
  /** Read by the host to decide when to delegate, so it states when the hub dispatches the spoke. */
  readonly description: string;
  /** The plugin skill that holds how the work is done. */
  readonly skill: string;
  readonly task: string;
  readonly payload: string;
}

// Routing metadata only. What a spoke is given and returns is its contract in
// `agents/hub/spokes/<id>.md`; how the work is done is the skill's.
const SPOKE_SUBAGENT_DEFINITIONS: readonly SpokeSubagentDefinition[] = [
  {
    id: 'explorer',
    description:
      'Use when the QA-AI-STLC hub dispatches an exploration: building or refreshing the selector registry for one environment, optionally from further start pages.',
    skill: 'qa-explore',
    task: 'an environment name and, optionally, further start pages to crawl',
    payload: 'the registry path and the element count `qa.explore` reported',
  },
  {
    id: 'test-design',
    description: 'Use when the QA-AI-STLC hub dispatches test case design for one feature or requirement.',
    skill: 'qa-design-cases',
    task: 'one feature or requirement id',
    payload: 'the ids of the cases you registered with `qa.cases_add`',
  },
  {
    id: 'case-execution',
    description:
      'Use when the QA-AI-STLC hub dispatches the live execution of one registered test case through the engine browser and HTTP tools.',
    skill: 'qa-execute',
    task: 'one registered test case id',
    payload: 'the case id and the result status `qa.case_result_register` recorded',
  },
  {
    id: 'test-generation',
    description:
      'Use when the QA-AI-STLC hub dispatches the generation of one deterministic spec from a case proven by qa-execute.',
    skill: 'qa-generate-tests',
    task: 'one test case id that has a proven session',
    payload: 'the case id, the spec path and the outcome `qa.generation_verify` returned',
  },
  {
    id: 'qa-rca',
    description: 'Use when the QA-AI-STLC hub dispatches the root cause analysis of one accepted defect.',
    skill: 'qa-rca',
    task: 'one accepted defect id',
    payload: 'the root cause analysis document you registered with `qa.rca_add`',
  },
];

export interface GeneratedSubagent {
  readonly spokeId: SpokeDefinitionId;
  /** Project-relative, with `/` separators. */
  readonly path: string;
  readonly content: string;
  /** Absent when the spoke has no configured model and so inherits the session's. */
  readonly model?: string;
}

function subagentName(id: SpokeDefinitionId): string {
  return id.startsWith('qa-') ? id : `qa-${id}`;
}

function renderSubagent(definition: SpokeSubagentDefinition, model: string | undefined): GeneratedSubagent {
  const name = subagentName(definition.id);
  const lines = [
    '---',
    `name: ${name}`,
    // A quoted scalar, so a colon in the text cannot end the value early.
    `description: ${JSON.stringify(definition.description)}`,
    ...(model === undefined ? [] : [`model: ${model}`]),
    '---',
    '',
    GENERATED_SUBAGENT_MARKER,
    '',
    `You are the \`${definition.id}\` spoke of the QA-AI-STLC hub. The hub gives you one task: ${definition.task}.`,
    '',
    `- Load the \`${definition.skill}\` skill and follow it for how the work is done.`,
    '- Work only from that task and from what engine tools (`qa.*`) return. Reach the application under test only through engine tools.',
    '- Never talk to the operator, approve a gate or call another spoke: the hub does that.',
    '- Finish with one JSON value and nothing after it: `{ "schemaVersion": 1, "spokeId", "taskId", "status": "ok", "payload" }`, or `status: "error"` with `error: { "code", "message" }` when you could not do the task. Use the `spokeId` and `taskId` the hub gave you.',
    `- The payload is ${definition.payload}. The hub checks it against the engine, so do not claim anything the engine did not record.`,
    '',
  ];
  return {
    spokeId: definition.id,
    path: `${SUBAGENT_DIRECTORY}/${name}.md`,
    content: lines.join('\n'),
    ...(model === undefined ? {} : { model }),
  };
}

/** One Claude Code subagent per spoke definition, with the `model:` the config routes it to. */
export function renderSpokeSubagents(models: AgentsConfig['models']): readonly GeneratedSubagent[] {
  return SPOKE_SUBAGENT_DEFINITIONS.map((definition) => renderSubagent(definition, models[definition.id]));
}

export function listSpokeDefinitionIds(): readonly SpokeDefinitionId[] {
  return SPOKE_SUBAGENT_DEFINITIONS.map((definition) => definition.id);
}
